    "question": "農業用パイプラインに使用される材料に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　鋼管は、普通炭素鋼で作られた管である。耐久性、耐衝撃性に優れるが、じん性、延性は低い。水管橋や内外圧の大きい管路に用いられるが、重量は比較的重く、軟弱地盤には適さない。電食に弱い性質を有するため、電食のおそれのある箇所では電食防止措置が必要である。\nB　プレストレストコンクリート管は、プレストレスを導入して製造されるコンクリート管である。耐久性が高く、重量も比較的重い。埋設管周辺の地下水質や土壌によってカバーコートモルタルの腐食が生じるおそれがある。\nC　強化プラスチック複合管は、不飽和ポリエステル樹脂、骨材、ガラス繊維を主原料として製造される管であり、重量は比較的軽く、運搬・施工が容易である。耐摩耗性に優れるが、管内面の粗度の変化は大きく、電食と衝撃に弱い性質を有する。\nD　硬質ポリ塩化ビニル管は、塩化ビニル重合体を主原料として可塑剤を添加せず押出し成形によって製造される管である。管内面の粗度の変化は小さく、滑らかである。軽量で取り扱いが容易であり、軟弱地盤に適しているが、熱、凍結、衝撃に弱い。",
