    "difficulty": 3,
    "question": "我が国のスマート農業技術に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。なお、データは「令和5年度 食料・農業・農村白書（令和6年5月31日公表）」による。\n\nA　農林水産省では、「農業分野におけるオープンAPI＊整備に関するガイドライン ver 1.0」を策定し、スマート農業技術の導入によって得られたデータの利活用によるデータ駆動型農業の実現を図っている。本ガイドラインに基づき、データ連携・共有・提供機能を有する協調領域として農業データ連携基盤（WAGRI）が、国立研究開発法人農業・食品産業技術総合研究機構を運営主体として、2019年より運営されている。\nB　自動走行農機などの先端技術の導入・利用の促進のためには、これら技術に対応した基盤整備の推進が重要である。進入路の設置やターン農道の利用に当たり、支線農道の路面高は、走行の安全性や維持管理などを考慮して可能な範囲で高くすることが効果的である。また、中山間地域における畦畔法面などの草刈り作業の軽減のため、法面の急勾配化も有効である。\nC　農林水産省では、2019年度からスマート農業実証プロジェクトを全国で推進している。水田作に関するスマート農業技術の導入効果を技術別にみると、慣行に比べ、農薬散布用ドローンで約6割、自動水管理システムで約8割、直進アシスト田植機で約2割の作業時間の短縮を図れることが明らかになっている。\nD　ドローンによる農薬などの空中散布を日中・夜間に目視内又は日中に目視外で行う場合、立入管理区画の設定などを行えば、操縦者の補助を行う者（ナビゲーター）を配置する必要はない。なお、航空法における「目視」とは、操縦者本人が自分の目でドローンを見ることを指し、モニターや双眼鏡、カメラなどを用いて見ることは「目視」には該当しない。\n\n＊　Application Programming Interface：複数のアプリケーション等を接続（連携）するために必要な仕組み",
