      "エ": "Cに示された機器の作業時間の短縮は実証結果に沿う。Bは、農機が安全に進入できるように農道との高低差を抑えることや、草刈りのための法面の緩勾配化を取り違えている。",
      "オ": "WAGRIは農研機構が運営するデータ連携基盤で、農薬散布や水管理ではスマート農業技術による時短が確認された。補助者を置かずに散布する場合は所定の立入管理措置などが前提で、目視には操縦者が自分の目で見ることが求められる。"
