    "question": "次は、モールの応力円に関する記述であるが、A、B、Cに当てはまるものの組合せとして最も妥当なのはどれか。\n\n「図1に示すような鉛直方向の応力 σᵥ と水平方向の応力 σₕ が生じた供試体内部の応力状態を、平面応力状態で考える。図2に示すような微小部分を考え、水平面から任意の角度 θ 傾いた平面での垂直応力を σθ、せん断応力を τθ としたとき、微小部分での力の釣合いを考えると、σθ 及び τθ はそれぞれ以下で表される。\nσθ = (σᵥ + σₕ)/2 + (σᵥ − σₕ) cos 2θ/2\nτθ = (σᵥ − σₕ) sin 2θ/2\n\nσθ 及び τθ は、垂直応力を横軸、せん断応力を縦軸とする座標上では図3のように表すことができ、これをモールの応力円と呼ぶ。せん断応力がゼロとなる面を［A］と呼び、モールの応力円を用いると、せん断応力が最大になる面は［A］から45°傾いた面となることが分かる。\n今、σᵥ = 160 kN/m²、σₕ = 40 kN/m² と与えられるとき、水平面から反時計回りに30°傾いた面に作用する τθ(θ = 30°) を計算すると［B］kN/m²となる。また、σₕ を40 kN/m²のまま、σᵥ を［C］kN/m²にすると、τθ(θ = 30°) は2倍となる。」",
    "choices": {
      "ア": "主応力面／30／280",
      "イ": "主応力面／30√3／240",
      "ウ": "主応力面／30√3／280",
      "エ": "中立面／30／280",
      "オ": "中立面／30√3／320"
    },
    "answer": "ウ",
    "officialAnswerNumber": 3,
    "explanation": "せん断応力がゼロの面は主応力面で、30°の面でのせん断応力は(160 − 40)sin 60°/2 = 30√3 kN/m²である。これを2倍にするには応力差を240 kN/m²とするため、鉛直応力は280 kN/m²になる。",
    "choiceExplanations": {
      "ア": "主応力面と280 kN/m²は合っている。θ = 30°で指定式のsin 2θを計算するとsin 60° = √3/2なので、Bには√3が付く。",
      "イ": "この角度でせん断応力を2倍にするには、鉛直応力と水平応力の差を120から240 kN/m²へ増やす。水平応力40 kN/m²を加えるので、鉛直応力は280 kN/m²になる。",
      "ウ": "せん断応力がゼロの面は主応力面で、30°の面でのせん断応力は(160 − 40)sin 60°/2 = 30√3 kN/m²である。これを2倍にするには応力差を240 kN/m²とするため、鉛直応力は280 kN/m²になる。",
      "エ": "せん断応力がゼロとなるのは、法線が主応力方向に一致する主応力面である。Bも、sin 60°を用いるため30√3 kN/m²となる。",
      "オ": "せん断応力がゼロの面は主応力面である。鉛直応力を320 kN/m²とすると差が280 kN/m²となり、元の差120 kN/m²の2倍を超える。"
    },
