    "difficulty": 3,
    "question": "流体の特性に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　流体の流れは、層流と乱流に区分することができる。この区分を与える指標をレイノルズ数という。層流と乱流は、ある値のレイノルズ数を閾値として明瞭に区分され、この閾値以上では層流、以下では乱流となることが分かっている。\nB　層流と乱流は、ガラス管の中を流れる水の場合、水と同程度の密度を持ったインクなどのトレーサーを上流から流し入れたときに、トレーサーが描く線の形状から判断することができる。層流の場合、トレーサーは管に平行な線を描くが、乱流の場合には不規則に波打ったり渦を巻いたりする。\nC　常流と射流との区分は、層流と乱流との区分とは異なる。そのため、常流には層流も乱流も存在し得る。河川を流下する水は一般に乱流となる場合が多い。また、土壌中の水移動に対してダルシー則が成立するのは、層流のときである。\nD　レイノルズ数は、慣性力と粘性力の積として定義される。慣性力は、管内の流れの場合には、その流速の最小速度と代表長さの積で表され、粘性力は、動粘性係数により表される。",
    "choices": {
      "ア": "B",
      "イ": "A、B",
      "ウ": "A、D",
      "エ": "B、C",
      "オ": "C、D"
    },
    "answer": "エ",
    "officialAnswerNumber": 4,
    "explanation": "層流では管に入れたトレーサーが明瞭な線を描き、乱流では流れに混ざって広がる。常流・射流の区分にはフルード数を用いるため、常流でも層流と乱流のどちらもあり得る。",
    "choiceExplanations": {
      "ア": "Bのトレーサーによる見分け方は妥当である。常流・射流を別の指標で分類するCも妥当である。",
      "イ": "Bは妥当だが、レイノルズ数が低い方で層流になりやすい。Aは層流と乱流の関係を逆にしており、遷移域も考慮していない。",
      "ウ": "レイノルズ数が大きい方では乱れが生じやすい。レイノルズ数は慣性力と粘性力の比で、Dのように積を取るわけではない。",
      "エ": "層流では管に入れたトレーサーが明瞭な線を描き、乱流では流れに混ざって広がる。常流・射流の区分にはフルード数を用いるため、常流でも層流と乱流のどちらもあり得る。",
      "オ": "Cの二つの流れの分類は妥当である。Dのレイノルズ数Re = UL/νでは、通常、管内の平均流速を代表流速Uとして用いる。"
    },
