    "question": "次は、調整池に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n「調整池は、用水計画における需要と供給の均衡をうまく保ち、取水量、水路中の通過流量及び用水量の三者の不均衡を調整して水管理損失を極力防止し、水路システムの［A］を有機的かつ弾力的なものにするために設けられるものである。\n水理的応答の速い［B］と応答の遅い［C］から構成される複合水路組織においては、流送の連続性確保の観点から、［B］と［C］の接合部に緩衝効果を持つ調整池などの導入が必要な場合が多い。\nまた、調整池は、配置によっては、一時的貯留効果を持つ［D］の遊水池としての機能を持たせることもできる。\n調整池の設計に当たっては、設置場所の地形、地質及び調整池の規模を考慮し、適切な構造形式を選定する。構造形式としては、河川などを締め切り、比較的大規模に設けられる［E］とファームポンドのような水槽形式に分類される。」",
