      "ウ": "Dの薄い水路部材に対する湿潤・保温養生は妥当である。Bは反応性が高い骨材を積極的に使用する点が適切でない。",
      "エ": "Cは土被りが過小な場合の地山の不安定化を踏まえている。Dも、比表面積の大きい薄い開水路で水分や温度を保つ養生が重要であることを示している。",
      "オ": "CとDは妥当だが、Aのように埋戻し土を弱くすれば薄い管でも安全にできるとはいえない。たわみ性管では、周辺の埋戻し土が管の横方向の変形を抑える。"
