    "difficulty": 3,
    "question": "コンクリートに関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　ワーカビリティ（workability）は、コンクリートの打ち込みやすさの程度及び材料の分離に抵抗する程度を示す用語である。ワーカビリティは、主に水量の多少による柔らかさの程度で示されるプラスチシティ（plasticity）に左右され、プラスチシティの一般的な測定方法として、ブリーディング試験がある。\nB　一般に、コンクリートは連続して打ち込むことが望ましいが、工程の都合などにより連続して打ち込めない場合は、打継目を設ける必要が生じる。打継目は構造物の弱点となりやすいため、水平打継目におけるレイタンスの除去や鉛直打継目における鉄筋の挿入など、新旧コンクリートが一体となるよう適切に処理する必要がある。\nC　無筋コンクリートにおいて問題となる劣化の一つに中性化がある。中性化は、硬化したコンクリートが空気中の二酸化炭素の作用を受けて次第にアルカリ性を失う現象であり、水セメント比が小さいほど中性化の速度が大きくなる。\nD　フレッシュコンクリートは、低温になると凝結・硬化が早くなるため、スランプが増加し、打込み・締固め・表面仕上げが困難になるなどの特徴があるため、練り混ぜたコンクリートの打込みを速やかに完了させるなど、特に注意を払う必要がある。",
    "choices": {
      "ア": "A",
      "イ": "B",
      "ウ": "A、C",
      "エ": "B、D",
      "オ": "C、D"
    },
    "answer": "イ",
    "officialAnswerNumber": 2,
    "explanation": "打継目は付着や一体性が不足すると弱点になる。水平打継目のレイタンスを除去するなど、接触面の状態や補強に配慮して新旧のコンクリートを打ち継ぐ。",
    "choiceExplanations": {
      "ア": "ブリーディング試験は打込み後に表面へ浮き出る水量などを測る。単位水量などの影響を受ける軟らかさの程度はコンシステンシーと呼ばれる。",
      "イ": "打継目は付着や一体性が不足すると弱点になる。水平打継目のレイタンスを除去するなど、接触面の状態や補強に配慮して新旧のコンクリートを打ち継ぐ。",
      "ウ": "Aにあるブリーディング試験は浮き水を評価する試験である。Cでは水セメント比が小さいほど組織が緻密になり、通常は中性化の進行が遅くなる。",
      "エ": "Bの打継目の処理は妥当である。低温では凝結や強度の発現が遅くなるため、Dは温度の影響を逆に述べている。",
      "オ": "中性化は鉄筋周囲のアルカリ性を失わせ、鉄筋腐食の原因にもなる。気温が低い場合には、凝結・硬化の遅れや初期凍害に配慮する。"
    },
