    "difficulty": 3,
    "question": "我が国のかんがいに関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　我が国の農業用水は、工業用水、上水道用水など他の水利用形態と比較して使用量が多く、水資源使用総量（取水量ベース）でみた場合、全体の約90％を占めている。また、農業用水のうち、約70％が水田かんがい用水として利用されている。\nB　水源から末端の水田まで用水を送る場合には、水路からの漏水、蒸発、還元水などによって損失する水量を考慮する必要がある。この水量の割合は水路の種類によって異なり、開水路では、一般に、ブロック積み水路、土水路、コンクリートライニング水路の順に大きい。\nC　農業用水を送水する上で、管水路は開水路と比較して、つぶれ地が少ない、経路の自由度が高い、汚濁水の途中流入がないといった点で優れている。ただし、管路では圧力の水理的な応答が長波の速度で伝わることに留意する必要がある上、管内の滞留空気の排除と通水急停止時の管内の空気の排除のため、通気スタンド、通気孔、空気弁の施設が必要である。\nD　水田へのかんがいの目的は、作物への水分補給、湛水による温度環境の調節、湛水による雑草・病害虫の抑制、塩分などの有害物質の除去、肥料・農薬の流入施用であり、その他に地域の水環境、生態系の保全などが挙げられる。",
