    "difficulty": 3,
    "question": "排水に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　排水計画を作成するに当たり、排水方式は、施設の設置費及び維持管理費が少なく済む自然排水方式を優先する。自然排水が不可能又は著しく難しい場合には、受益区域内を高位部と低位部に分割して高位部を機械排水、低位部を自然排水とすることや、常時は自然排水、洪水時は外水位が低い期間のみ機械排水とすることを検討する。\nB　排水計画では、排水解析に必要な湛水深と湛水量の関係（H-V曲線）、湛水深と湛水面積の関係（H-A曲線）の作成、排水路の路線などを検討するため、少なくとも0.5 m間隔程度の等高線が必要である。ただし、国土基本図は1/5,000地図で5.0 m間隔、1/2,500地図で2.0 m間隔であるため、ほ場面標高の資料収集や水準点測量を追加して0.5 m間隔の等高線を加えて補足する必要がある。\nC　排水ポンプの台数は設備の信頼性を高めるために、複数台とすることが望ましい。ポンプ排水を導入する地区の地形は、一般に低平地で幹線排水路の河床の勾配が緩く、排水路の流れがポンプ運転と連動しない場合がある。この場合、遊水池の容量検討とともに、それに接続する幹線排水路の通水能力の検討が特に重要である。\nD　排水計画上、水稲の冠水被害が最も大きい穂ばらみ期を考慮し、水田の許容湛水深は50 cmを標準としている。経済的な施設規模とするため、許容湛水深を超える湛水計画も許されるが、その場合は、許容湛水深以上の継続時間は30時間を限度とする。",
    "choices": {
      "ア": "A、B",
      "イ": "A、C",
      "ウ": "B、C",
      "エ": "B、D",
      "オ": "C、D"
    },
