    "officialAnswerNumber": 3,
    "explanation": "緩い起伏まで捉える等高線は、湛水深に応じた面積や貯留量を把握するために必要である。ポンプと幹線排水路の能力が合わない場合には、遊水池の容量と水路の通水能力を併せて検討する。",
