    "difficulty": 3,
    "question": "我が国のほ場整備に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。なお、データは「令和5年度 食料・農業・農村白書（令和6年5月31日公表）」による。\n\nA　我が国の基幹的農業従事者数は、平成12年（2000年）の約240万人から令和5年までに約30％減少しており、その平均年齢は約60歳となっている。今後も農業者の減少が見込まれる中、生産性の高い農業を確立するため、自動走行農機などのスマート農業技術の導入に資するほ場の大区画化やデジタル基盤の整備が推進されている。\nB　水田の再整備における区画拡大の手法として、畦抜き工法と道路抜き工法がある。現況の用排水路や農道の改変を伴う道路抜き工法に対し、畦抜き工法は、現況の用排水路や農道は基本的に改変せず、畦畔を取り除いて耕区の長辺方向に区画を拡大する工法であり、傾斜が大きい地形でも土工量が少なく済むため傾斜地に適している。\nC　主食用米の作付面積が一貫して減少する中、海外依存度の高い小麦及び大豆の令和5年産の作付面積は、いずれも前年産に比べ増加している。今後も主食用米の需要の減少が見込まれる中、需要に応じた生産を促進するため、田畑輪換を可能にする水田の汎用化に加え、水田の畑地化が推進されている。\nD　水田の汎用化は、通常の肥培管理で麦・大豆などの畑作物や野菜を栽培できるよう、水田に排水路や暗渠を整備して水はけを良くすることであり、計画排水量は、10年に1回程度発生する確率雨量において、4時間で降った雨量を4時間で排水することを目標として決定する。",
