    "question": "我が国の畑地の整備に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　汎用耕地とは、稲作と畑作のいずれにも対応可能な土地基盤条件を持っている耕地のことである。物理性の変化の点からみると、畑から水田への転換後、土壌は、団粒構造が発達し、粗間隙は増加する。一方、水田から畑への転換後は、化学性の変化として、鉄やマンガンの下層への沈殿集積などが生じる。\nB　畑のほ場整備は、水田のほ場整備に比べて、作物の種類の多様性、畑の種類の多様性、営農計画の重要性、工事の特殊性、工事後における土地条件差の存続性、標準区画採用の困難性、農地保全対策の重要性などの特徴を有しており、事業計画を作成するに当たり留意が必要である。\nC　普通畑は植生が少なく畦畔がないため、浸透流が発生すると水田や樹園地に比べ土壌が侵食されやすい。このため、透水性が高い地区や降雨強度の大きい地区では、地形をうまく利用しながら浸透流の排水系統を適切に整備し、速やかに排水させることが必要である。\nD　かんがい施設は、経済的で管理が容易であることが望ましい。かんがい頻度の高い労働集約型作物畑では地表定置式の施設が導入されることが多く、かんがい頻度の低い土地利用型作物畑では地表定置式より経済的に有利な移動式の大型散水器が導入されることが多い。",
