    "difficulty": 3,
    "question": "次は、暗渠排水に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n「畑地及び水田の畑利用における暗渠排水の目標は雨水の排除である一方、水田の暗渠排水の目標は表層残留水と［A］内に停滞する過剰水を計画排水時間内に排除することである。暗渠の深さ、間隔などの暗渠排水組織は数値的に決定できるが、暗渠排水の効果を決定するのは主に暗渠溝の構造であり、暗渠溝底面から［A］の下まで疎水材を投入して透水性を確保することが重要である。\nまた、暗渠排水設備は維持管理が必須であり、［B］は、暗渠排水機能の維持や土壌の透水性改良効果が期待できる一方、［C］は不透水層を形成するおそれがあり、暗渠機能の低下の原因となる。このような場合、耕盤層を［D］して通水機能を回復させる必要がある。\n暗渠排水計画は、土壌など地区の特性に応じて作成することが重要である。我が国には数タイプの特殊土壌が存在し、泥炭土壌において暗渠排水を施工すると、乾燥による泥炭の分解により透水性の著しい［E］や排水効果の発現による地盤の沈下や不等沈下が生じる危険性があるため、暗渠排水の計画に当たっては留意が必要である。」",
    "choices": {
      "ア": "耕盤層／中干しや間断かんがい／代かき／破壊／増大",
      "イ": "耕盤層／中干しや間断かんがい／代かき／構築／低下",
      "ウ": "耕盤層／代かき／中干しや間断かんがい／構築／増大",
      "エ": "作土層／中干しや間断かんがい／代かき／破壊／低下",
      "オ": "作土層／代かき／中干しや間断かんがい／破壊／低下"
    },
    "answer": "エ",
    "officialAnswerNumber": 4,
    "explanation": "暗渠は作土層に停滞する水を排除し、中干しや間断かんがいは通水性の維持に役立つ。代かきによって耕盤の透水性が低下した場合は破壊して回復を図り、泥炭の乾燥では透水性の低下や地盤沈下に注意する。",
