    "difficulty": 3,
    "question": "土地改良法及び土地改良事業に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　土地改良事業とは、農業用用排水施設、農業用道路その他農用地の保全又は利用上必要な施設の新設、管理、廃止又は変更や、区画整理、農用地の造成などを行う事業であり、土地改良事業に埋立て又は干拓を行う事業は含まれない一方、農村の基礎的な生活環境の向上を図る農業集落排水事業は土地改良事業に含まれる。\nB　土地改良長期計画は、計画期間に係る農業生産の選択的拡大、農業の生産性の向上及び農業総生産の増大の見通し並びに農業経営の規模の拡大等農業構造の改善の方向に即し、かつ、国土資源の総合的な開発及び保全に資するように定めるものとされており、5年を1期とし、計画期間に係る土地改良事業の実施の目標と事業量を定めるものとされている。\nC　国営土地改良事業は、受益者の私的財産である農用地の利用関係に影響を及ぼし、事業に要する費用負担を求めることなどから、原則として受益者からの申請、3分の2以上の同意が必要とされている。ただし、土地改良区に関係する土地改良施設の更新事業であって、一定の要件を満たす場合には、受益者からの同意徴集手続の省略が可能となっている。\nD　土地改良区の設立に係る申請人は、土地改良法第三条に規定する資格（以下「三条資格」という。）を有する者10人以上であることを要する。また、三条資格に係る土地を含む一定の地域を定め、その地域に係る土地改良事業の施行を目的として、国の認可を受け、その地域について土地改良区を設立することができる。",
