      "イ": "間断日数に相当する連続干天期間において、作物による吸水や土壌面蒸発によって土壌水分量が減少する土層を制限土層と呼び、制限土層内で水分消費に最も支配的な役割を果たし、その層の水分状態が作物の生育に直接影響を与える土層を有効土層と呼ぶ。",
      "ウ": "土壌間隙網の毛管力によって発生するポテンシャルエネルギーをマトリックポテンシャルと呼び、毛管内に存在する水には大気圧以上の圧力が働いているため、マトリックポテンシャルは、負圧となる。また、マトリックポテンシャルは、その絶対値を水頭（cmH₂O）に換算したpF（potential of free water energy）値として表す場合もある。",
      "エ": "土壌湿潤度と浸透ポテンシャルとの関係をグラフで表現したものを土壌の水分特性曲線といい、脱水法と吸水法で測定された両者の関係をプロットしても一般には同じ曲線にはならない。この現象はヒステリシスと呼ばれ、溶質の水相と固相への分配特性が変化することで生じる。",
      "オ": "土壌中の無限少量の水を純水の形で基準位置に引き抜くのに必要な水の単位量当たりのエネルギー量を全ポテンシャルと呼ぶ。全ポテンシャルの構成要素の一つである重力ポテンシャルは、土壌水の化学的な状態や圧力条件には関係なく、相対的な高さだけで変化する。"
