      "イ": "雨滴や地表面を流下する水などにより土壌が侵食される現象を水食という。水食は、侵食の形態により、ガリ侵食、リル侵食、面状侵食などに分けられる。細流状の侵食をガリ侵食といい、ガリ侵食が大きく発達したものをリル侵食、リル侵食が広範囲に起きる侵食を面状侵食という。",
