    "question": "中山間地域の農業に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。なお、データは「令和5年度 食料・農業・農村白書（令和6年5月31日公表）」による。\n\nA　農林水産省は、中山間地農業ルネッサンス事業の枠組みの下、日本型直接支払制度を構成する四つの直接支払制度のうちの一つである中山間地域等直接支払制度や、米、野菜、果樹などの栽培や畜産、林業も含めた中山間地における多様な複合経営を推進する農山漁村振興交付金などの支援制度を実施している。\nB　中山間地域等直接支払制度について、令和2年度から始まった第5期対策では、担い手不足や集落機能の弱体化などに対応するため、新たな人材の確保や集落機能の強化、集落協定の広域化、棚田地域の振興を図る取組などに対して加算措置を設けている。令和4年度の同制度の協定数は前年度より増加して2万4千協定となり、協定面積も前年度より増加して65万6千haとなった。\nC　令和5年に公表した「中山間地域等直接支払制度 第5期対策中間年評価書」によると、集落協定が実施している主な共同活動としては、「活動の中心となる次期リーダーの育成」が最も多い。一方、令和6年度末に集落協定を廃止する意向を持っている地域のうち、その多くは既に地域農業が自立し、農山村の環境整備が軌道に乗ったことを理由に直接支払制度から卒業すると回答している。\nD　「デジ活」中山間地域は、農林水産業の「仕事づくり」を軸として、一定の研修を受けた外部人材の投入を条件に、デジタル技術などを主体的に活用できる地域住民を育成することにより、社会課題解決に向けた取組を積み重ねることで活性化を図る地域である。「デジ活」中山間地域は、第2期「まち・ひと・しごと創生総合戦略」におけるモデル地域ビジョンの一つとして位置付けられている。",
