    "difficulty": 3,
    "question": "環境の経済評価に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　ヘドニック法は、環境が財の市場価格に影響を及ぼすことに着目して、市場価格に反映された環境の外部効果を計測することで環境の価値を評価する方法である。この方法は顕示選好法の一種であり、大気や水質の清浄さといった様々な環境の質の評価に用いられている。\nB　トラベルコスト法は、環境を再生するために必要となる費用、あるいは環境サービスと同様のサービスを提供するために必要とされる費用により評価する方法である。この方法では、環境の利用価値だけでなく非利用価値を評価することも可能である。\nC　仮想評価法（CVM）は、環境変化が市場の財・サービスの生産変化と結び付いている場合、その生産額の変化量を用いて環境変化の貨幣評価を行う方法である。この方法の問題点は、評価対象が生物多様性のような非利用価値に限定されることである。\nD　コンジョイント分析は、アンケート調査を用いて、環境を改善する様々な代替案に対する好みを尋ねることで、環境の価値を評価する方法である。この方法は表明選好法の一種であり、一度に複数のサービスを評価することができる。",
    "choices": {
      "ア": "A、B",
      "イ": "A、D",
      "ウ": "B、C",
      "エ": "B、D",
      "オ": "C、D"
    },
