      "ア": "観光庁は、中山間地域で農泊に取り組もうとする個人に対し、体制整備、食事・体験に関する観光コンテンツの開発、古民家を活用した宿泊施設の整備などを単独で支援している。農泊を推進する狙いは、長時間の滞在と消費により農山漁村における「しごと」を作り出し、持続的な収益を確保して雇用を生み出すとともに、農山漁村への移住・定住も見据えた関係人口の創出の入口とすることにある。",
