      "ウ": "農村関係人口の拡大に向けては、農山漁村への関心や関与の強弱に応じて複線型のアプローチが重要である。例えば農業体験などで農山漁村に触れた都市住民が、援農ボランティア、二地域居住を経て、就農のために農山漁村に移住する場合や、都市農村交流を発展させ、都市に居住しながらも特定の農村に継続的に関わることで消費拡大や共同活動への参加を通じた集落機能の補完などを進める場合が想定される。",
