    "question": "都市住民と農業に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。なお、データは「令和5年度 食料・農業・農村白書（令和6年5月31日公表）」による。\n\nA　都市農業は、都市住民に対して農業体験・学習の場や災害時の避難場所の提供、都市住民の生活への安らぎを提供するなどの多様な機能を有しており、全国の農地面積のうち市街化区域にある農地の割合は1割程度となっている。その一方で、都市に近接することから大気や地下水の汚染の影響を強く受け、また、農地が分散しており産地化やブランド化が困難であるため、農業産出額は全国の約1％に過ぎない。\nB　都市農業の機能の一つとして、農業・農地が身近に存在することで都市住民が農業に触れる機会も増加するなど、都市住民の農業への理解を醸成する役割がある。レクリエーション、高齢者の生きがいづくり、生徒・児童の体験学習などの目的で、農家でない者が小さな面積の農地を利用して自家用の野菜や花を栽培する農園のことを一般に、市民農園や農業体験農園等と呼ぶ。\nC　持続可能な農村を創造するためには、都市住民などが農業・農村に関わることで農村ファンともいうべき「農村関心層」を創出し、「農村関係人口」の創出・拡大や関係の深化を図っていく必要がある。一方、内閣府が令和5年に実施した世論調査によると、特産品の購入やふるさと納税、定期的な農村への訪問などの、農村地域との関わりが現在ないと答えた人が約4割おり、今後も農村地域と関わりを持ちたくないと答えた人は約5％いた。\nD　内閣官房、総務省、文部科学省、農林水産省、環境省は、子供の農山漁村での宿泊による農林漁業体験や自然体験活動などを行う事業である「農山漁村アントレプレナーシップ」を通じ、都市農村交流を推進している。同事業は、子供たちの農業を学ぶ意欲や自立心を育み、農業高校及び農業大学校への進学、ひいては就農を後押しするものであり、これらの生徒、学生の約7割が卒業と同時に就農し、将来の担い手の育成・確保につながっている。",
