    "question": "農村の整備に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　農村地域においては、農業水利施設の管理の省力化・高度化やスマート農業の実装、地域の活性化を図るため、ICT等の活用に向けた情報通信環境を整備することが重要な課題となっている。農林水産省は、総務省と連携して、農村における光ファイバ、無線基地局、公衆無線LANなどの施設整備を支援している。\nB　農道は、ほ場への通作や営農資機材の搬入、産地から市場までの農産物の輸送などに利用され、地域の生産性向上などに資するほか、地域住民の日常的な移動に利用されるなど、農村の生活環境の改善を図る重要なインフラである。土地改良事業で造成された幅員1.8 m以上の農道のうち、道路法の適用を受けず、農道として管理されている全ての農道については、延長、幅員、構造などの基礎的諸元が図面と共に農道台帳に整理されている。\nC　農業集落排水施設とは、農業集落におけるし尿、生活雑排水などの汚水、汚泥を処理する施設をいう。汚水処理には物理的処理、化学的処理及び生物的処理の各方式がある。一般に、微生物の活動に適した温度や水質などを制御する生物的処理方式は、薬剤により処理を行う化学的処理方式と比較して、処理費用が高価になるので、農業集落排水は特別な場合を除き、物理的処理方式及び化学的処理方式の組合せで処理することが一般的である。\nD　営農飲雑用水施設は、育苗、病害虫防除、家畜の飼養、農産物及び農業用機械の洗浄などのための営農用水と併せて、衛生的かつ近代的な農業生活を実現するための飲用水や生活用水のほか、防火用水や公園用水といった集落雑用水などの供給を目的とする施設である。飲用水や生活用水として使用する場合は、原則として水道法に基づく水質基準を満たす必要があるが、それ以外の場合は、原則として農業用水水質基準を満たせば良い。",
