    "question": "歯車に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　かみ合う一対の歯車のうち、歯数の多い方の歯車を大歯車あるいはギアといい、歯数の少ない方の歯車を小歯車あるいはピニオンという。大歯車のピッチ円筒の径が無限大に大きくなったものをラックという。図aは、小歯車とかみ合うラックであり、ピッチ面は平面となる。\nB　図bのように、歯すじがつる巻き線である円筒歯車をはすば歯車という。強度的には平歯車より優れているが、かみ合い長さが長いため、振動・騒音が大きくなる。したがって、低速回転で使用される歯車装置などで用いられる。\nC　図cのように、ねじれの位置にある二つの円すいを点接触させ、この円すいをピッチ面とする食い違い軸の歯車をまがりば傘歯車という。まがりば傘歯車は、軸がねじれの位置にあるため、歯車の両側に軸受けを設けることができる。ただし、小歯車のねじれが大きいため、歯の強度が低い。\nD　図dのように、ウォームとウォームホイールからなる歯車対をウォームギアという。一組のウォームとウォームホイールのみで大きな減速が可能であるが、歯面間の相対的滑りが大きいため、回転運動の伝達効率は低い。",
