    "question": "トラクタの動力伝達装置に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　トラクタのクラッチは、主クラッチ、変速クラッチ、PTOクラッチ、かじ取りクラッチ、デフロッククラッチに分類される。主クラッチは、エンジンの動力の伝達を断続させる装置であり、エンジン始動時やエンジンを回転させた状態で走行を停止する、又は変速を行う場合に操作する。\nB　トラクタの変速装置は、一般に主変速と副変速の組合せによる多段変速となっており、自動車と比べて減速比が小さく変速段数が多い特徴がある。主変速で低速、中速、高速と大レンジの速度を選択し、副変速で作業条件に合わせて細かく変速することができる。\nC　車輪トラクタの旋回を容易にするために、内外車輪に回転速度の差を与える機構が差動装置である。トラクタが直進するときは、左右車輪は同じ回転速度となるが、旋回時に内側車輪の負荷が増大すると、内側車輪が増速して、外側車輪が減速する。\nD　終減速装置は、変速装置や差動装置によって減速された回転を更に減速させることで車輪に伝達する装置であり、その機構には平歯車式、はすば歯車式、遊星歯車式、傘歯車式などがある。一般に四輪駆動トラクタには、前輪、後輪それぞれに終減速装置が配置されている。",
