    "question": "一般的な農業機械用のエンジンに関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA　2サイクルエンジンは、吸気された混合気で燃焼ガスを追い出すため、排出されたガスに未燃ガスなどが含まれることとなり、環境面からは好ましくない。一方、4サイクルエンジンと比べて構造がシンプルであるなどメリットも多く、現在でも刈払機などで利用されている。\nB　田植機は低速時に高いトルクが必要であり、主としてディーゼルエンジンが搭載されてきた。歩行型田植機には、小型の単気筒ディーゼルエンジンが搭載され、10条を一度に植え付ける大型の乗用型田植機には、より高いトルクを発生する3～4気筒のディーゼルエンジンが搭載されている。\nC　エンジンオイルの主要な役割として、潤滑作用、密封作用、保温作用、清浄作用が挙げられる。4サイクルエンジンに用いるエンジンオイルは、燃焼室に混合気と共に供給され燃焼されるため、逐次補充が必要である。\nD　圧縮比は、シリンダ内の最大容積を最小容積で除した値のことで、一般にディーゼルエンジンは、ガソリンエンジンより圧縮比が高い。圧縮比を高めることで、エンジンは高出力・高効率となるが、そのためには頑丈な構造が求められるため、ディーゼルエンジンはガソリンエンジンに比べて重くなる傾向にある。",
