    "explanation": "2サイクルでは掃気の際に未燃の混合気が排気へ出ることがあるが、簡素な構造を生かし小型機に用いられる。ディーゼルエンジンは空気を高い圧縮比で圧縮するため、圧力に耐える丈夫な構造を要する。",
