    "question": "次は、トラクタの三点リンク機構に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n「トラクタは、三点リンク機構によって各種作業機を取り付けることで様々な作業を行うことができる。三点リンクによる作業機の昇降には大きな力が必要であり、油圧によって動作する。作業機の位置を制御するポジションコントロールとは、操作レバーによって［A］を上下させ、作業機をトラクタに対して常に一定の位置で停止・固定し、作業高さを一定に制御することを指す。また、［B］は、ロータリ耕の耕深を［C］の動きによって検出し、設定された耕深を一定に保つように制御することを指す。さらに、水平制御は、軟弱地などでタイヤが沈んでトラクタが左右に傾いても、［D］に組み込まれたシリンダを伸縮させることによって、作業機を水平に保つように制御することを指す。」",
