    "question": "農畜産廃棄物の利活用技術に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　堆肥化のための適正な水分量は、牛ふんを主とした原料では湿潤重量ベースで60％近傍にあることが知られている。この適正値よりも高い水分量の原料であった場合、稲わらやおが粉などの乾いた副資材を水分調整材として混合する。\nB　有機物中の炭素と窒素との比を示すC/N比は、堆肥化過程の進行具合の評価や最終製品の安定度を示す指標として重要である。一般に、C/N比は植物系資材で小さく、動物系資材で大きくなり、C/N比が低いほど分解しにくく、高いほど分解しやすい。\nC　メタン発酵において、バイオガス中に含まれる硫化水素の除去は、設備の腐食や大気汚染を防ぐ上で重要である。乾式脱硫法は水やアルカリ水溶液に硫化水素を溶解させる方法であり、湿式脱硫法は水酸化第二鉄を成形した成形脱硫剤を充填したガス吸収塔にバイオガスを通し、硫化水素を硫化鉄として脱硫剤に吸収させる方法である。\nD　燃焼脱臭装置は、臭気ガスを600～800℃の燃焼炉で燃焼させ、悪臭物質を酸化分解する脱臭装置である。燃焼法ではほぼ完全に脱臭できるため、高濃度の臭気にも対応できる。装置の設置面積は小さいが、化石燃料を必要とするため運転コストが大きくなる。",
