    "question": "温室Aを細霧冷房、温室Bを電気ヒートポンプにより、それぞれ日中に冷房し、温室内の気温を維持することを想定する（温室の床面積はいずれも1000 m²）。下記の条件の下、1時間当たりの細霧冷房で必要な水の量（kg·hr⁻¹）と電気ヒートポンプの消費電力量（kWh）の組合せとして最も妥当なのはどれか。\nただし、細霧冷房で用いられる水は湿度に関係なく、全て温室内で蒸発するものとする。また、温室外日射量は、70％が温室内で吸収されて熱になるものとし、その熱量が蒸発潜熱又は電気ヒートポンプにより温室外に排出されるものとし、換気、地中伝熱、被覆資材などを介しての熱通過による熱の移動は無視できるものとする。\n\n条件　温室外日射量：750 W m⁻²\n　　　水の蒸発潜熱：2500 J g⁻¹ K⁻¹\n　　　電気ヒートポンプの冷房時成績係数（COP）：3.0",
