    "question": "農業生産における気候資源に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA　有効積算気温とは、ある基準気温以上では気温が高いほど植物生産に寄与するとの考え方に基づき、日平均気温から基準気温を引いた差あるいは日平均気温について、それぞれ日平均気温が基準気温以上の日のみ積算したものである。基準気温として、10℃又は5℃が用いられることが多い。\nB　温量指数（暖かさの指数）は、日平均気温から基準気温10℃を引いた差を正の値のみ積算したものである。この指数を基に日本の植生は、南から亜熱帯林、暖温帯落葉広葉樹林、照葉樹林、冷温帯落葉広葉樹林、亜寒帯針葉樹林などに区分される。\nC　作物の乾物1 gを生産するのに必要な水分量を要水量又は蒸散係数と呼ぶ。イネやダイズなどのC₃植物の要水量はトウモロコシなどのC₄植物の要水量と比べて大きい。\nD　植物の総光合成量に呼吸量を加えた値を純生産量といい、年間、単位面積当たりの純生産量を純一次生産力（NPP）と呼ぶ。筑後モデルでは、年平均気温と年間降水量からNPPを推定する。",
